import wave,numpy as np
w=wave.open('/workspace/work/cal2.wav'); p=w.getparams(); a=np.frombuffer(w.readframes(p.nframes),dtype='<i2').reshape(-1,2)
for ch in range(2):
    x=a[:,ch].astype(float)
    def dom(seg):
        win=np.hanning(len(seg)); sp=np.abs(np.fft.rfft(seg*win)); fr=np.fft.rfftfreq(len(seg),1/44100)
        return round(fr[np.argmax(sp)],2), int(np.abs(seg).max())
    print('ch',ch,'row0',dom(x[0:int(4*p.nframes/256)]),'row32',dom(x[int(32*p.nframes/256):int(36*p.nframes/256)]))
""}

